//! Plain Melee lookup tables and action-state helpers.
//!
//! The tables mirror slippi-js's `melee/*.json` (characters, stages, moves, aerial frame data)
//! and are generated by `tools/verify-stats/gen-tables.mjs`. The action-state constants and
//! predicates mirror slippi-js's `stats/common.ts`.

#[rustfmt::skip]
mod tables;

pub mod state;

use serde::{Deserialize, Serialize};

/// A playable (or special) character, keyed by *external* character id: the id used in game
/// settings and on the character select screen (Captain Falcon = 0, Fox = 2, ...).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CharacterInfo {
    /// External character id.
    pub id: u8,
    /// Full name, e.g. "Captain Falcon".
    pub name: &'static str,
    /// Short name, e.g. "Falcon".
    pub short_name: &'static str,
    /// Costume color names, indexed by costume index. Index 0 is always "Default".
    pub colors: &'static [&'static str],
}

impl CharacterInfo {
    /// Number of costumes (including the default one).
    pub fn costume_count(&self) -> usize {
        self.colors.len()
    }
}

/// What a stage is used for.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum StageMode {
    /// A normal versus stage.
    Vs,
    /// A Break the Targets stage.
    TargetTest,
    /// The Home-Run Contest stage.
    HomeRunContest,
    /// A debug-only stage.
    Debug,
}

/// A stage, keyed by stage id (as in game settings).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct StageInfo {
    /// Stage id.
    pub id: u16,
    /// Display name, e.g. "Final Destination".
    pub name: &'static str,
    /// What the stage is used for.
    pub mode: StageMode,
}

/// A move, keyed by the attack id Melee reports in a character's "last attack landed".
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MoveInfo {
    /// Move (attack) id.
    pub id: u8,
    /// Long name, e.g. "Forward Smash".
    pub name: &'static str,
    /// Short name, e.g. "fsmash".
    pub short_name: &'static str,
}

/// All known characters, sorted by external id. Ids 0..=25 are playable; 26..=32 are special
/// (Master Hand, Wireframes, Giga Bowser, Crazy Hand, Sandbag, Popo).
pub fn characters() -> &'static [CharacterInfo] {
    tables::CHARACTERS
}

/// Playable characters only (external ids 0..=25), sorted by id.
pub fn playable_characters() -> &'static [CharacterInfo] {
    let n = tables::CHARACTERS.iter().take_while(|c| c.id <= 25).count();
    &tables::CHARACTERS[..n]
}

/// Looks up a character by external character id.
pub fn character(external_id: u8) -> Option<&'static CharacterInfo> {
    tables::CHARACTERS.iter().find(|c| c.id == external_id)
}

/// Full character name, or "Unknown Character" (as slippi-js does).
pub fn character_name(external_id: u8) -> &'static str {
    character(external_id).map_or("Unknown Character", |c| c.name)
}

/// Short character name, or "Unknown" (as slippi-js does).
pub fn character_short_name(external_id: u8) -> &'static str {
    character(external_id).map_or("Unknown", |c| c.short_name)
}

/// Number of costumes for a character (including the default). 1 for unknown characters.
pub fn costume_count(external_id: u8) -> usize {
    character(external_id).map_or(1, CharacterInfo::costume_count)
}

/// Costume color name for a character and costume index; "Default" if unknown.
pub fn costume_name(external_id: u8, costume: u8) -> &'static str {
    character(external_id)
        .and_then(|c| c.colors.get(costume as usize).copied())
        .unwrap_or("Default")
}

/// All known stages, sorted by id.
pub fn stages() -> &'static [StageInfo] {
    tables::STAGES
}

/// Looks up a stage by stage id.
pub fn stage(id: u16) -> Option<&'static StageInfo> {
    tables::STAGES.iter().find(|s| s.id == id)
}

/// Stage name, or "Unknown Stage" (as slippi-js does).
pub fn stage_name(id: u16) -> &'static str {
    stage(id).map_or("Unknown Stage", |s| s.name)
}

/// All known moves, sorted by id.
pub fn moves() -> &'static [MoveInfo] {
    tables::MOVES
}

/// Looks up a move by move (attack) id.
pub fn move_info(id: u8) -> Option<&'static MoveInfo> {
    tables::MOVES.iter().find(|m| m.id == id)
}

/// Long move name, or "Unknown Move" (as slippi-js does).
pub fn move_name(id: u8) -> &'static str {
    move_info(id).map_or("Unknown Move", |m| m.name)
}

/// Short move name, or "unknown" (as slippi-js does).
pub fn move_short_name(id: u8) -> &'static str {
    move_info(id).map_or("unknown", |m| m.short_name)
}

/// Which way a character died, from the action state they were in on the frame they lost the
/// stock (see [`crate::Stock::death_animation`]). Mirrors slippi-js `getDeathDirection`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum DeathDirection {
    /// Bottom blast zone.
    Down,
    /// Left blast zone.
    Left,
    /// Right blast zone.
    Right,
    /// Top blast zone (star KO or screen KO).
    Up,
}

/// Death direction for a death action state, or `None` if `action_state` isn't a dying state.
pub fn death_direction(action_state: u16) -> Option<DeathDirection> {
    match action_state {
        0 => Some(DeathDirection::Down),
        1 => Some(DeathDirection::Left),
        2 => Some(DeathDirection::Right),
        3..=0xa => Some(DeathDirection::Up),
        _ => None,
    }
}

/// Aerial landing lag `(normal, l_cancelled)` for an internal character id and aerial landing
/// action state (`AERIAL_NAIR_LANDING..=AERIAL_DAIR_LANDING`), from slippi-js's frame data.
pub fn aerial_landing_lag(internal_character_id: u8, landing_state: u16) -> Option<(u8, u8)> {
    let aerial = match landing_state {
        state::AERIAL_NAIR_LANDING => 0,
        state::AERIAL_FAIR_LANDING => 1,
        state::AERIAL_BAIR_LANDING => 2,
        state::AERIAL_UAIR_LANDING => 3,
        state::AERIAL_DAIR_LANDING => 4,
        _ => return None,
    };
    tables::AERIAL_LANDING_LAG
        .get(internal_character_id as usize)
        .map(|row| row[aerial])
}

/// Internal character ids (the ids used in frame data, which differ from external ids).
pub mod internal {
    /// Peach (internal id), who has unique forward smash action states.
    pub const PEACH: u8 = 0x09;
    /// Mr. Game & Watch (internal id), who has unique action states for several attacks.
    pub const GAME_AND_WATCH: u8 = 0x18;
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn lookups() {
        assert_eq!(character_name(0), "Captain Falcon");
        assert_eq!(character_short_name(0), "Falcon");
        assert_eq!(character_short_name(2), "Fox");
        assert_eq!(costume_count(2), 4);
        assert_eq!(costume_name(2, 1), "Red");
        assert_eq!(costume_name(2, 9), "Default");
        assert_eq!(character_name(200), "Unknown Character");
        assert_eq!(playable_characters().len(), 26);
        assert_eq!(stage_name(32), "Final Destination");
        assert_eq!(stage_name(31), "Battlefield");
        assert_eq!(stage_name(0), "Unknown Stage");
        assert_eq!(move_short_name(2), "jab");
        assert_eq!(move_name(250), "Unknown Move");
        assert_eq!(death_direction(1), Some(DeathDirection::Left));
        assert_eq!(death_direction(0xb), None);
        // Fox (internal 1) dair: 18 / 9.
        assert_eq!(
            aerial_landing_lag(1, state::AERIAL_DAIR_LANDING),
            Some((18, 9))
        );
        assert_eq!(aerial_landing_lag(0x1b, state::AERIAL_DAIR_LANDING), None);
    }
}
